            if(!Set.of("EXPENSE","CAPITAL").contains(treatment))throw new IllegalArgumentException("Select expense or capital treatment.");String target="CAPITAL".equals(treatment)?"CAPITALIZED":"EXPENSED";if(target.equals(r.getString("statusId")))return result(r,"Y");if(!"OPEN".equals(r.getString("statusId")))throw new IllegalArgumentException("This cost is already returned or settled.");
            operational(d,a);if(!"FAM_COMPLETED".equals(maintenance(d,a,r.getString("maintHistSeqId")).getString("statusId")))throw new IllegalArgumentException("Complete maintenance before settling its costs.");boolean admin=c.getSecurity().hasEntityPermission("ASSETS","_ADMIN",u);if(!admin&&!c.getSecurity().hasEntityPermission("ASSETS","_APPROVE",u))throw new IllegalArgumentException("Assets approval permission is required.");finance(c,u);AssetsDisposalServices.requireSeparateApprover(r.getString("createdByUserLogin"),u.getString("userLoginId"),admin,"Y".equals(in.get("onBehalf")));
            String org=a.getString("partyId"),currency=baseCurrency(d,org);if(!currency.equals(r.getString("currencyUomId")))throw new IllegalArgumentException("Organization base currency changed; reconcile this cost first.");AssetsGlMappingServices.validateAccount(d,org,r.getString("expenseGlAccountId"),"EXPENSE",UtilDateTime.nowTimestamp());verifySource(d,r);
            if("CAPITAL".equals(treatment)&&!"Y".equals(in.get("acceptFullMonthPolicy")))throw new IllegalArgumentException("Explicitly approve full-month prospective depreciation over remaining life before capitalizing.");
